	}](r)
	if err != nil {
		return nil, err
	}
	return s.SetEnvGroupFile(r.Context(), r.PathValue("id"), r.PathValue("name"), req.Content)
}))
mux.HandleFunc("GET /v1/env-groups/{id}/secret-files/{name}", core.HandleJSON(http.StatusOK, func(r *http.Request) (any, error) {
